<script setup>
import {ref,onMounted,onUnmounted,computed,reactive,watch} from 'vue';import {useRoute,useRouter} from 'vue-router';import {api,messageOf} from '../api';import {auth,initializeAuth} from '../auth';import {freshnessLabel,isConfirmationStale,formatShanghai} from '../time';import {createLatestRequest} from '../latestRequest';import {runOperationOnce} from '../operationGuard'
const route=useRoute(),router=useRouter(),item=ref(null),slots=ref([]),interest=ref(null),interestList=ref([]),comments=ref([]),loading=ref(true),pending=reactive(new Set()),error=ref(''),notice=ref(''),selected=ref(null),comment=ref(''),replyingId=ref(null),replyText=ref('');const pickup=reactive({location:'',startAt:'',endAt:''});
const mine=computed(()=>auth.user&&item.value&&auth.user.id===item.value.publisher.id),canWant=computed(()=>auth.user&&!mine.value&&item.value?.status==='AVAILABLE'),statusText=computed(()=>({AVAILABLE:'可领取',RESERVED:'待交接',COMPLETED:'已送出'}[item.value?.status]||''));
const topComments=computed(()=>comments.value.filter(c=>c.parentId==null).map(c=>({...c,replies:comments.value.filter(r=>r.parentId===c.id)})));
const detailRequests=createLatestRequest();
async function load(){loading.value=true;error.value='';item.value=null;interest.value=null;interestList.value=[];const id=route.params.id;try{const result=await detailRequests.run(async signal=>{const authInitialization=initializeAuth();const [itemResponse,slotResponse,commentResponse]=await Promise.all([api.get(`/items/detail/${id}`,{signal}),api.get(`/items/${id}/slots`,{signal}),api.get(`/items/${id}/comments`,{signal})]);await authInitialization;let ownInterest=null,receivedInterests=[];if(auth.user){if(auth.user.id===itemResponse.data.publisher.id)receivedInterests=(await api.get(`/items/${id}/interests`,{signal})).data;else ownInterest=(await api.get(`/items/${id}/interests/mine`,{signal})).data}return {item:itemResponse.data,slots:slotResponse.data,comments:commentResponse.data,interest:ownInterest,interestList:receivedInterests}});if(!result.accepted)return;item.value=result.value.item;slots.value=result.value.slots;comments.value=result.value.comments;interest.value=result.value.interest;interestList.value=result.value.interestList;pickup.location=item.value.pickupLocation||'';loading.value=false}catch(e){error.value=messageOf(e);loading.value=false}}
const isPending=key=>pending.has(key);async function act(key,fn,msg){const result=await runOperationOnce(pending,key,async()=>{error.value='';notice.value='';try{await fn();notice.value=msg;await load();return true}catch(e){error.value=messageOf(e);return false}});return result.executed&&result.value===true}
const want=()=>{if(!auth.user)return router.push('/login');return act('interest',()=>api.post(`/items/${item.value.id}/interests`,{slotId:selected.value,expectedItemVersion:item.value.version}),'已提交意向，等待发布者确认。')};const cancelInterest=()=>act('interest',()=>api.delete(`/items/${item.value.id}/interests/mine`),'意向已取消。');const confirm=id=>act('confirm-interest',()=>api.post(`/interests/${id}/confirm`),'已确认领取人，物品进入待交接。');const confirmAvailable=()=>act('availability',()=>api.post(`/items/${item.value.id}/confirm-available`),'已确认物品仍在。');
const savePickup=()=>act('pickup',()=>api.post(`/items/${item.value.id}/pickup-options`,{location:pickup.location,slots:[{startAt:`${pickup.startAt}:00`,endAt:`${pickup.endAt}:00`}]}),'交接信息已保存。');async function sendComment(){if(!auth.user)return router.push('/login');if(await act('comment',()=>api.post(`/items/${item.value.id}/comments`,{content:comment.value}),'留言已发布。'))comment.value=''}
function openReply(id){replyingId.value=replyingId.value===id?null:id;replyText.value='';error.value='';notice.value=''}
async function sendReply(parentId){const text=replyText.value;if(await act(`reply:${parentId}`,()=>api.post(`/items/${item.value.id}/comments/${parentId}/replies`,{content:text}),'回复已发布。')){replyText.value='';replyingId.value=null}}
function price(i){return i.tradeType==='FREE'?'免费送':i.tradeType==='NEGOTIABLE'?'随便给':`¥${Number(i.price).toFixed(2)}`}
onMounted(load);watch(()=>route.params.id,load);onUnmounted(detailRequests.cancel)
</script>
<template><p v-if="loading" class="state">加载详情中…</p><p v-else-if="error&&!item" class="state error">{{error}} <button @click="load">重试</button></p><div v-else-if="item" class="detail-page"><article class="detail"><img :src="item.imageUrl" alt="物品占位图"><div><div class="meta-row"><span class="pill">{{statusText}}</span><span class="freshness">{{freshnessLabel(item.publishedAt)}}</span></div><p class="eyebrow">{{item.category}} · {{item.publisher.nickname}} 发布</p><h1>{{item.title}}</h1><strong class="price">{{price(item)}}</strong><p class="description">{{item.description}}</p><div class="time-panel"><p>发布于：{{formatShanghai(item.publishedAt)}}</p><p>最近确认：{{formatShanghai(item.lastConfirmedAt)}}</p><p v-if="isConfirmationStale(item.lastConfirmedAt)" class="stale">状态较久未更新，建议先询问</p><p v-if="item.pickupLocation">公共交接地点：{{item.pickupLocation}}</p></div><div v-if="mine&&item.status==='AVAILABLE'" class="owner-actions"><button :disabled="isPending('availability')" @click="confirmAvailable">{{isPending('availability')?'确认中…':'确认还在'}}</button><RouterLink class="secondary-link" :to="`/items/${item.id}/edit`">编辑物品</RouterLink></div></div></article>
<section class="panel"><h2>交接时段</h2><p v-if="!slots.length" class="state">暂无有效未来时段。</p><div v-else class="stack"><label v-for="s in slots" :key="s.id" class="choice"><input v-if="canWant" v-model="selected" type="radio" :value="s.id">{{formatShanghai(s.startAt)}} 至 {{formatShanghai(s.endAt)}}</label></div><template v-if="canWant"><p v-if="interest">当前意向：<strong>{{interest.status==='WAITING'?'等待发布者确认':interest.status==='CONFIRMED'?'已确认':'已取消'}}</strong></p><button :disabled="isPending('interest')||!selected" @click="want">{{isPending('interest')?'提交中…':'我想要'}}</button> <button v-if="interest?.status==='WAITING'" class="secondary" :disabled="isPending('interest')" @click="cancelInterest">取消意向</button></template><p v-if="!auth.user&&item.status==='AVAILABLE'"><RouterLink to="/login">登录后选择时段并表达想要</RouterLink></p></section>
<section v-if="mine&&item.status==='AVAILABLE'&&!slots.length" class="panel"><h2>补充交接信息</h2><label>公共地点<input v-model="pickup.location" maxlength="200"></label><div class="form-row"><label>开始<input v-model="pickup.startAt" type="datetime-local"></label><label>结束<input v-model="pickup.endAt" type="datetime-local"></label></div><button :disabled="isPending('pickup')" @click="savePickup">{{isPending('pickup')?'保存中…':'保存地点和时段'}}</button></section>
<section v-if="mine" class="panel"><h2>意向名单</h2><p v-if="!interestList.length" class="state">暂无意向。</p><div v-for="x in interestList" :key="x.id" class="list-row"><div><strong>{{x.nickname}}</strong><p>{{formatShanghai(x.startAt)}} 至 {{formatShanghai(x.endAt)}} · {{x.status}}</p></div><button v-if="x.status==='WAITING'&&item.status==='AVAILABLE'" :disabled="isPending('confirm-interest')" @click="confirm(x.id)">{{isPending('confirm-interest')?'确认中…':'确认此人'}}</button></div></section>
<section class="panel comments-panel"><h2>公开留言</h2><p v-if="!topComments.length" class="state">暂无留言。</p><article v-for="c in topComments" :key="c.id" class="comment-thread"><div class="comment"><strong>{{c.nickname}}</strong><p>{{c.content}}</p><div class="comment-meta"><small>{{formatShanghai(c.createdAt)}}</small><button v-if="mine&&item.status!=='COMPLETED'" type="button" class="text-button" @click="openReply(c.id)">{{replyingId===c.id?'收起':'回复'}}</button></div></div><div v-for="r in c.replies" :key="r.id" class="comment reply"><strong>发布者回复</strong><p>{{r.content}}</p><small>{{formatShanghai(r.createdAt)}}</small></div><form v-if="replyingId===c.id&&mine&&item.status!=='COMPLETED'" class="reply-form" @submit.prevent="sendReply(c.id)"><label>回复内容<textarea v-model="replyText" maxlength="500" required rows="2" placeholder="公开回复这条问题"></textarea></label><div class="reply-actions"><button :disabled="isPending(`reply:${c.id}`)">{{isPending(`reply:${c.id}`)?'提交中…':'发布回复'}}</button><button type="button" class="secondary" :disabled="isPending(`reply:${c.id}`)" @click="openReply(c.id)">取消</button></div></form></article><form v-if="item.status!=='COMPLETED'" class="new-comment-form" @submit.prevent="sendComment"><label>留言<textarea v-model="comment" maxlength="500" required rows="3" placeholder="公开询问物品情况，请勿留下私人联系方式"></textarea></label><button :disabled="isPending('comment')">{{isPending('comment')?'提交中…':'发布留言'}}</button></form><p v-else class="state">已送出物品的留言与回复为只读。</p></section><p v-if="notice" class="success">{{notice}}</p><p v-if="error" class="error">{{error}}</p></div></template>
